import Foundation
import RooflineCore

// Checks for the bank-card photo sizing (CardSizing.swift).
//
// PARITY with the server is the point. CardSizing is a line-for-line port of the server's packages/shared/src/window-photo-card.ts
// (sizeFromCard, cardProblem, inchesInWords), so the checks run it on photos whose answers were GENERATED by running that real
// TypeScript (CardParityData.swift, with the recipe in its header) and compare number for number: widthIn, heightIn, both
// uncertainties, distanceIn, viewAngleDeg and sizeRatio within 1e-6 relative (they are the same math in doubles; in practice
// they agree to the last digit or two), quality, reasons and the 422 sentence by equality.
//
// The photos are the model's own territory: window sizes from 12 x 18 to 72 x 80 in at about 4 ft, views at 0 to 66 degrees,
// 13 to 120 mm lenses and photos that say nothing about theirs, 3024 x 4032, 4032 x 3024 and other photo sizes, tap noise,
// the card tapped clockwise, counter-clockwise and from every corner, cards that are small or not card-shaped, windows that
// cannot be sized (crossing, a dart, three in a line, a size outside 3...400 in), mistaps, the real answer the server's API
// doc prints, and every sentence cardProblem says. The other checks pin the model on their own (a noise-free sweep must give
// the window back, the tap order must not matter), the corner ordering the app does before it sends, and that no garbage
// crashes the live preview.

// MARK: - Synthetic photos for the corner order checks

/// The window glass (a plane, inches, y down) seen by a camera: a known homography from plane inches to photo pixels, so
/// every corner is projected exactly and the truth is known.
private struct CardCheckScene {
    var pxPerIn: Double
    var windowWIn: Double
    var windowHIn: Double
    var rotationDeg = 1.5
    /// Perspective as the plane's depth change per photo pixel, so a scene looks the same at any scale.
    var perspX = 1e-5
    var perspY = -7.5e-6
    var offset = Vec2(300, 280)

    /// The reference scene: about 40 px per inch, 1.5 degrees of turn, a small perspective term, a 35.625 x 59.625 in window.
    static let reference = CardCheckScene(pxPerIn: 40, windowWIn: 35.625, windowHIn: 59.625)

    var matrix: [Double] {
        let a = rotationDeg * .pi / 180
        return [pxPerIn * cos(a), -pxPerIn * sin(a), offset.x, pxPerIn * sin(a), pxPerIn * cos(a), offset.y, perspX * pxPerIn, perspY * pxPerIn, 1]
    }

    /// The point through the 3x3 projective matrix (row-major).
    func photo(_ x: Double, _ y: Double) -> Vec2 {
        let h = matrix
        let w = h[6] * x + h[7] * y + h[8]
        return Vec2((h[0] * x + h[1] * y + h[2]) / w, (h[3] * x + h[4] * y + h[5]) / w)
    }

    /// The window frame's corners in the photo: TL, TR, BR, BL.
    var window: [Vec2] { [photo(0, 0), photo(windowWIn, 0), photo(windowWIn, windowHIn), photo(0, windowHIn)] }

    /// A rectangle on the glass with its top-left at plane (x, y) inches, turned `tiltDeg` about its centre: TL, TR, BR, BL.
    func rectangle(x: Double, y: Double, w: Double, h: Double, tiltDeg: Double = 0) -> [Vec2] {
        let cx = x + w / 2, cy = y + h / 2, t = tiltDeg * .pi / 180
        return [(-w / 2, -h / 2), (w / 2, -h / 2), (w / 2, h / 2), (-w / 2, h / 2)].map { c in
            photo(cx + c.0 * cos(t) - c.1 * sin(t), cy + c.0 * sin(t) + c.1 * cos(t))
        }
    }

    /// The bank card lying near the window's lower-left corner, `marginPx` (at this scene's scale) in from the edges.
    func card(portrait: Bool = false, tiltDeg: Double = 0, marginPx: Double = 60) -> [Vec2] {
        let w = portrait ? CardLimits.heightIn : CardLimits.widthIn
        let h = portrait ? CardLimits.widthIn : CardLimits.heightIn
        let m = marginPx / pxPerIn
        return rectangle(x: m, y: windowHIn - m - h, w: w, h: h, tiltDeg: tiltDeg)
    }
}

/// A seeded linear congruential generator (Knuth's MMIX constants) with Box-Muller: no system randomness, so every run of
/// a check sees the same numbers.
private struct CardRNG {
    var state: UInt64

    mutating func unit() -> Double {
        state = state &* 6364136223846793005 &+ 1442695040888963407
        return (Double(state >> 11) + 0.5) / 9007199254740992
    }

    mutating func gaussian() -> Double {
        let u1 = unit(), u2 = unit()
        return (-2 * log(u1)).squareRoot() * cos(2 * Double.pi * u2)
    }
}

/// All 24 orders of the indexes 0...3.
private func cardPermutations() -> [[Int]] {
    var out: [[Int]] = []
    func go(_ prefix: [Int], _ rest: [Int]) {
        if rest.isEmpty {
            out.append(prefix)
            return
        }
        for (i, x) in rest.enumerated() {
            var r = rest
            r.remove(at: i)
            go(prefix + [x], r)
        }
    }
    go([], [0, 1, 2, 3])
    return out
}

/// Length of the edge from corner i to corner i + 1.
private func cardEdge(_ q: [Vec2], _ i: Int) -> Double {
    hypot(q[(i + 1) % 4].x - q[i].x, q[(i + 1) % 4].y - q[i].y)
}

/// Shoelace area, positive when the corners run clockwise on a screen (y down).
private func cardSignedArea(_ q: [Vec2]) -> Double {
    var s = 0.0
    for i in 0..<q.count {
        let a = q[i], b = q[(i + 1) % q.count]
        s += a.x * b.y - b.x * a.y
    }
    return s / 2
}

// MARK: - Synthetic photos for the sizing checks (the server tests' pinhole camera)

/// A pinhole camera `distanceIn` from a target on the glass, swung by yaw (about the vertical) and pitch, looking at the
/// target. The glass is the plane z = 0 (x right, y down, inches, z into the wall).
private struct CardCamera {
    let position: Vec3
    let right: Vec3
    let down: Vec3
    let forward: Vec3
    let focalPx: Double
    let w: Double
    let h: Double

    init(distanceIn: Double, yawDeg: Double, pitchDeg: Double, focalPx: Double, w: Double, h: Double, target: Vec3) {
        let yaw = yawDeg * Double.pi / 180
        let pitch = pitchDeg * Double.pi / 180
        position = Vec3(target.x + distanceIn * sin(yaw) * cos(pitch), target.y - distanceIn * sin(pitch), -distanceIn * cos(yaw) * cos(pitch))
        forward = (target - position).normalized!
        right = forward.cross(Vec3(0, -1, 0)).normalized!
        down = forward.cross(right)
        self.focalPx = focalPx
        self.w = w
        self.h = h
    }

    func project(_ p: Vec3) -> Vec2 {
        let d = p - position
        let cam = Vec3(right.dot(d), down.dot(d), forward.dot(d))
        return Vec2(focalPx * (cam.x / cam.z) + w / 2, focalPx * (cam.y / cam.z) + h / 2)
    }
}

private struct CardShot {
    var winW: Double
    var winH: Double
    var yawDeg: Double
    var pitchDeg = 0.0
    var distanceIn: Double
    var offsetIn = 1.0
    /// The photo's shape: tall (3024 x 4032) or wide (4032 x 3024). Default: tall for a window at least as tall as wide.
    var tallPhoto: Bool?
    /// The lens the picture was taken with (35 mm equivalent).
    var focal35 = 26.0
    /// Do not back the camera off to fit the window in the photo.
    var exact = false
}

private struct CardPlacement {
    /// The card lies portrait on the glass.
    var portrait = false
    var rotDeg = 0.0
    var centre: Vec2?
    var rectScale = Vec2(1, 1)
}

private struct CardPhoto {
    var widthPx: Double
    var heightPx: Double
    var focalPx: Double
    var windowQuad: [Vec2]
    var cardQuad: [Vec2]
    var distanceIn: Double
}

/// One photo of a shot: the camera backs off from `distanceIn` until the window's corners are inside the photo (unless
/// `exact`). The window frame's corners lie `offsetIn` in front of the glass, the card is ON it; its taps are at the TIPS of
/// its rounded corners (the inset rectangle).
private func cardPhoto(_ s: CardShot, _ c: CardPlacement = CardPlacement()) -> CardPhoto {
    let tall = s.tallPhoto ?? (s.winH >= s.winW)
    let w = tall ? 3024.0 : 4032.0
    let h = tall ? 4032.0 : 3024.0
    let focalPx = s.focal35 / 36 * max(w, h)
    let target = Vec3(s.winW / 2, s.winH / 2, 0)
    var distanceIn = s.distanceIn
    func make() -> CardCamera { CardCamera(distanceIn: distanceIn, yawDeg: s.yawDeg, pitchDeg: s.pitchDeg, focalPx: focalPx, w: w, h: h, target: target) }
    func windowQuad(_ cam: CardCamera) -> [Vec2] {
        let corners: [(Double, Double)] = [(0, 0), (s.winW, 0), (s.winW, s.winH), (0, s.winH)]
        return corners.map { cam.project(Vec3($0.0, $0.1, -s.offsetIn)) }
    }
    var cam = make()
    var tries = 0
    while tries < 400 && !s.exact {
        if windowQuad(cam).allSatisfy({ $0.x > 0.05 * w && $0.x < 0.95 * w && $0.y > 0.05 * h && $0.y < 0.95 * h }) { break }
        distanceIn *= 1.02
        cam = make()
        tries += 1
    }
    let centre = c.centre ?? Vec2(s.winW / 2, s.winH / 2)
    let rot = (c.rotDeg + (c.portrait ? 90 : 0)) * (Double.pi / 180)
    let hw = CardLimits.tapRectWidthMm / CardLimits.mmPerInch * c.rectScale.x / 2
    let hh = CardLimits.tapRectHeightMm / CardLimits.mmPerInch * c.rectScale.y / 2
    let local: [(Double, Double)] = [(-hw, -hh), (hw, -hh), (hw, hh), (-hw, hh)]
    let card = local.map { uv in
        cam.project(Vec3(centre.x + uv.0 * cos(rot) - uv.1 * sin(rot), centre.y + uv.0 * sin(rot) + uv.1 * cos(rot), 0))
    }
    return CardPhoto(widthPx: w, heightPx: h, focalPx: focalPx, windowQuad: windowQuad(cam), cardQuad: card, distanceIn: distanceIn)
}

/// The four taps in another order: start at corner `start`, optionally going round the other way.
private func cardTapOrder(_ q: [Vec2], _ start: Int, _ reverse: Bool) -> [Vec2] {
    let a = reverse ? [q[0], q[3], q[2], q[1]] : q
    return (0..<4).map { a[($0 + start) % 4] }
}

/// All 16 ways a person might tap a card: portrait or landscape on the glass, either winding, any starting corner.
private let cardLayouts: [(portrait: Bool, reverse: Bool, start: Int)] = [false, true].flatMap { portrait in
    [false, true].flatMap { reverse in (0..<4).map { (portrait: portrait, reverse: reverse, start: $0) } }
}

private let cardInchesPerMetre = 39.37

private func cardInput(_ p: CardPhoto, card: [Vec2]? = nil, window: [Vec2]? = nil, offset: Double? = nil, focalSigma: Double? = nil, tap: Double? = nil) -> CardSizeInput {
    CardSizeInput(widthPx: p.widthPx, heightPx: p.heightPx, focalPx: p.focalPx, focalSigmaFrac: focalSigma, cardCorners: card ?? p.cardQuad, windowCorners: window ?? p.windowQuad, planeOffsetIn: offset, tapSigmaPx: tap)
}

// MARK: - Comparing with the server

/// Equal within a relative `rel` of the server's number (an absolute `floor` for numbers at zero).
private func cardClose(_ got: Double, _ want: Double, rel: Double = 1e-6, floor: Double = 1e-12) -> Bool {
    if got == want { return true }
    if got.isNaN && want.isNaN { return true }
    return abs(got - want) <= rel * abs(want) + floor
}

/// One answer against the server's: the numbers within a relative 1e-6, quality and reasons exactly, nil when the server's is.
private func cardCompare(_ ctx: CheckContext, _ name: String, _ got: CardSize?, _ size: [Double]?, _ quality: String, _ reasons: [String]) {
    guard let want = size else {
        ctx.expect(got == nil, "\(name): the server cannot size it, we returned \(String(describing: got))")
        return
    }
    guard let got = got else {
        ctx.expect(false, "\(name): the server sizes it, we returned nil")
        return
    }
    let fields: [(String, Double, Double, Double)] = [
        ("widthIn", got.widthIn, want[0], 1e-12), ("heightIn", got.heightIn, want[1], 1e-12),
        ("uncertainty width", got.uncertaintyWidthIn, want[2], 1e-12), ("uncertainty height", got.uncertaintyHeightIn, want[3], 1e-12),
        ("distanceIn", got.distanceIn, want[4], 1e-12),
        // acos is not well conditioned at 0 degrees: one ulp in the cosine is about 1e-6 degrees there
        ("viewAngleDeg", got.viewAngleDeg, want[5], 1e-5),
        ("sizeRatio", got.sizeRatio, want[6], 1e-12),
    ]
    for (label, g, w, floor) in fields {
        ctx.expect(cardClose(g, w, floor: floor), "\(name): \(label) \(g), the server's \(w)")
    }
    ctx.equal(got.quality.rawValue, quality, "\(name): quality")
    ctx.equal(got.reasons, reasons, "\(name): reasons")
}

private func cardParityCase(_ name: String) -> CardParityCase? { cardParityCases.first { $0.name == name } }

