        ctx.equal(CardSizing.usableFocal35mm(8), 8)
        ctx.equal(CardSizing.usableFocal35mm(600), 600)
        ctx.equal(CardSizing.usableFocal35mm(26.4), 26.4)
        ctx.equal(CardSizing.usableFocal35mm(7.9), nil)
        ctx.equal(CardSizing.usableFocal35mm(.nan), nil)
        // size() is sizeFromCard with the focal length in pixels and the doubt the server picks
        let side = max(told.widthPx, told.heightPx)
        let direct = CardSizing.sizeFromCard(CardSizeInput(widthPx: told.widthPx, heightPx: told.heightPx, focalPx: 26.0 / 36 * side, focalSigmaFrac: 0.1, cardCorners: told.cardCorners, windowCorners: told.windowCorners))
