    Check("CardSizing.size: the +/- grows with the window and the angle, and 'check' is exactly a larger +/- than 3/8 in") { ctx in
        func maxU(_ r: CardSize) -> Double { max(r.uncertaintyWidthIn, r.uncertaintyHeightIn) }
        func size(_ shot: CardShot, tap: Double? = nil) -> CardSize? { CardSizing.sizeFromCard(cardInput(cardPhoto(shot), tap: tap)) }
        let sizes: [(Double, Double)] = [(12, 18), (24, 36), (36, 60), (48, 72), (72, 80)]
        var previous: CardSize?
        for (w, h) in sizes {
            guard let r = size(CardShot(winW: w, winH: h, yawDeg: 15, pitchDeg: 3, distanceIn: 3 * cardInchesPerMetre, exact: true)) else {
                ctx.expect(false, "\(w)x\(h): nil")
                continue
            }
            if let p = previous {
                ctx.expect(maxU(r) > maxU(p), "\(w)x\(h): +/- \(maxU(r)) after \(maxU(p))")
                ctx.expect(r.sizeRatio > p.sizeRatio, "\(w)x\(h): ratio")
            }
            previous = r
        }
        func angle(_ yaw: Double, _ metres: Double) -> Double { size(CardShot(winW: 36, winH: 60, yawDeg: yaw, pitchDeg: 2, distanceIn: metres * cardInchesPerMetre, exact: true)).map(maxU) ?? .nan }
        ctx.expect(angle(0, 2) < angle(30, 2) && angle(30, 2) < angle(55, 2), "the +/- grows with the angle")
        ctx.expect(angle(15, 1) < angle(15, 2) && angle(15, 2) < angle(15, 3), "the +/- grows with the distance")
        // The line sits at 3/8, not above or below: find the tap noise that makes the larger +/- exactly 3/8
        let mid = cardPhoto(CardShot(winW: 24, winH: 36, yawDeg: 10, distanceIn: 1.5 * cardInchesPerMetre))
        func with(_ tap: Double) -> CardSize? { CardSizing.sizeFromCard(cardInput(mid, tap: tap)) }
        var lo = 0.0, hi = 50.0
        guard let atZero = with(0), maxU(atZero) < CardLimits.checkAboveIn else {
            ctx.expect(false, "no tap noise is under 3/8")
            return
        }
        for _ in 0..<80 {
            let m = (lo + hi) / 2
            if let r = with(m), maxU(r) <= CardLimits.checkAboveIn { lo = m } else { hi = m }
        }
        if let r = with(lo), let over = with(hi) {
            ctx.near(maxU(r), 0.375, 1e-9, "at the line")
            ctx.equal(r.quality, .good)
            ctx.expect(!r.reasons.contains { $0.contains("off by about") }, "\(r.reasons)")
            ctx.equal(over.quality, .check)
            ctx.expect(over.reasons.contains { $0.contains("off by about") }, "\(over.reasons)")
        } else {
            ctx.expect(false, "the two sides of the line")
        }
    },
