    Check("CardSizing.size: what cannot be sized is nil (crossing, a dart, a line, five corners, a size outside 3...400 in, not a number) and problem says why") { ctx in
        let good = cardPhoto(CardShot(winW: 36, winH: 60, yawDeg: 15, distanceIn: 1.5 * cardInchesPerMetre))
        let base = cardInput(good)
        let c = good.cardQuad, w = good.windowQuad
        func size(_ i: CardSizeInput) -> CardSize? { CardSizing.sizeFromCard(i) }
        func problem(card: [Vec2]? = nil, window: [Vec2]? = nil, width: Double? = nil, height: Double? = nil) -> String? {
            CardSizing.problem(cardCorners: card ?? c, windowCorners: window ?? w, imageWidthPx: width ?? good.widthPx, imageHeightPx: height ?? good.heightPx)
        }
