        ctx.equal(problem(), nil, "a good capture has no problem")
        // Card corners
        let line = [c[0], Vec2(c[0].x + 40, c[0].y + 10), Vec2(c[0].x + 80, c[0].y + 20), Vec2(c[0].x + 120, c[0].y + 30)]
        let three = [c[0], Vec2((c[0].x + c[1].x) / 2, (c[0].y + c[1].y) / 2), c[1], c[2]]
        let bowtie = [c[0], c[2], c[1], c[3]]
        let dart = [c[0], c[1], Vec2(c[0].x + 0.4 * (c[2].x - c[0].x), c[0].y + 0.4 * (c[2].y - c[0].y)), c[3]]
        for (name, q) in [("a line", line), ("three in a line", three), ("a bow tie", bowtie), ("a dart", dart), ("two the same", [c[0], c[1], c[1], c[3]])] {
