            ctx.expect(problem(card: q) != nil, "card: \(name) has a sentence")
        }
        ctx.expect(problem(card: bowtie)?.contains("cross over each other") == true, "\(String(describing: problem(card: bowtie)))")
        ctx.expect(problem(card: line)?.contains("do not make the shape of a card") == true)
        ctx.expect(problem(card: [c[0], c[1], c[3], c[2]])?.contains("cross over each other") == true, "the other pair of sides crossing")
        // Window corners
        let wline = [w[0], Vec2(w[0].x + 100, w[0].y + 50), Vec2(w[0].x + 200, w[0].y + 100), Vec2(w[0].x + 300, w[0].y + 150)]
        let wbow = [w[0], w[2], w[1], w[3]]
        let wdart = [w[0], w[1], Vec2(w[0].x + 0.4 * (w[2].x - w[0].x), w[0].y + 0.4 * (w[2].y - w[0].y)), w[3]]
        for (name, q) in [("a line", wline), ("a bow tie", wbow), ("a dart", wdart)] {
            ctx.expect(size(cardInput(good, window: q)) == nil, "window: \(name)")
            ctx.expect(problem(window: q) != nil, "window: \(name) has a sentence")
        }
        ctx.expect(problem(window: wbow)?.contains("Mark them in order: top left, top right, bottom right, bottom left") == true)
        ctx.expect(problem(window: wline)?.contains("do not make the shape of a window") == true)
        ctx.expect(problem(window: wdart)?.contains("do not make the shape of a window") == true)
        // Counts and numbers that are not numbers
        ctx.expect(size(cardInput(good, card: Array(c.prefix(3)))) == nil && problem(card: Array(c.prefix(3)))?.contains("card corners are outside the photo") == true, "three card corners")
        ctx.expect(size(cardInput(good, window: w + [w[0]])) == nil && problem(window: w + [w[0]])?.contains("window corners are outside the photo") == true, "five window corners")
        ctx.expect(size(cardInput(good, card: [])) == nil && size(cardInput(good, window: [])) == nil, "no corners")
        ctx.expect(problem(card: [c[0], Vec2(.nan, 5), c[2], c[3]])?.contains("outside the photo") == true, "NaN")
        ctx.expect(size(cardInput(good, card: [c[0], Vec2(.nan, 5), c[2], c[3]])) == nil, "NaN card")
        ctx.expect(size(cardInput(good, window: [w[0], Vec2(.infinity, 5), w[2], w[3]])) == nil, "infinite window")
        ctx.equal(problem(width: 0), "The photo could not be read. Take it again.")
        ctx.equal(problem(height: .nan), "The photo could not be read. Take it again.")
        ctx.equal(problem(width: -1), "The photo could not be read. Take it again.")
