        ctx.expect(size(CardSizeInput(widthPx: good.widthPx, heightPx: good.heightPx, focalPx: 0, cardCorners: c, windowCorners: w)) == nil, "no focal length")
        ctx.expect(size(cardInput(good, tap: -1)) == nil && size(cardInput(good, offset: .nan)) == nil && size(cardInput(good, offset: 9)) == nil && size(cardInput(good, focalSigma: -0.1)) == nil, "options out of range")
        // A card too tiny to tap is refused with a sentence; a small one is only flagged
        let mid = Vec2((c[0].x + c[2].x) / 2, (c[0].y + c[2].y) / 2)
        func shrink(_ k: Double) -> [Vec2] { c.map { Vec2(mid.x + ($0.x - mid.x) * k, mid.y + ($0.y - mid.y) * k) } }
        ctx.expect(problem(card: shrink(0.15))?.contains("too small in this photo") == true)
