        ctx.expect(size(cardInput(cardPhoto(CardShot(winW: 450, winH: 420, yawDeg: 0, distanceIn: 15 * cardInchesPerMetre, exact: true)))) == nil, "450 x 420 in")
        // A frame nearer the camera than the camera is to the glass: the frame offset larger than the distance
        let close = cardPhoto(CardShot(winW: 36, winH: 60, yawDeg: 0, distanceIn: 4, exact: true))
        ctx.expect(size(cardInput(close, offset: 5)) == nil, "the frame is behind the camera")
        ctx.expect(size(cardInput(good, offset: 5.9)) != nil, "5.9 in of offset is accepted")
    },
    Check("CardSizing: the app's flow, the corners ordered for the API in any tap order, sizes like the clockwise taps") { ctx in
